CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261108225753_CriacaoInicial') THEN
    CREATE TABLE "Clientes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "NomeCompleto" text NOT NULL,
        "CPF" text NOT NULL,
        "DataNascimento" timestamp with time zone NOT NULL,
        "Email" text NOT NULL,
        CONSTRAINT "PK_Clientes" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261108225753_CriacaoInicial') THEN
    CREATE TABLE "Dividas" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "ClientId" integer NOT NULL,
        "Valor" numeric NOT NULL,
        "Paga" boolean NOT NULL,
        "DataCriacao" timestamp with time zone NOT NULL,
        "DataPagamento" timestamp with time zone,
        CONSTRAINT "PK_Dividas" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261108225753_CriacaoInicial') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261108225753_CriacaoInicial', '10.0.14');
    END IF;
END $EF$;
COMMIT;

